import java.util.Scanner;
public class JThreeBoolean2 {
	public static void main(String[] args) {
		//Khutwa 1: Iqra madakhulat al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-mutaghayyir al-booli al-awwal (true aw false):");
		boolean a = scan.nextBoolean();		
		System.out.println("Adkhil qimat al-mutaghayyir al-booli al-thani (true aw false):");
		boolean b = scan.nextBoolean();	
		System.out.println("Adkhil qimat al-mutaghayyir al-booli al-thalith (true aw false):");
		boolean c = scan.nextBoolean();		
		scan.close();
		//Khutwa 2: Iktub taabir booli li-tahdid law kana ahad ala al-aqal min thalath mutaghayyirat booliyya khata
		boolean value = !(a && b && c);
		System.out.println(value);
	}
}
